  let reportedUsage: AggregateUsage | undefined;
  const hooks: OrchestratorHooks = {
    afterModelResponse: async (_session, _text, usage) => {
      reportedUsage = usage;
    },
  };

  let round = 0;
  const provider: AIProvider = {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      if (round === 0) {
        round++;
        yield {type: 'tool_use', toolCall: {id: 'c1', name: 'tool', input: {}}};
        // Missing inputTokens and totalTokens at runtime
        yield usageStop('tool_use', {outputTokens: 5} as any);
        return;
      }
      yield {type: 'text', text: 'done'};
      yield usageStop('end_turn', {inputTokens: 10, outputTokens: 5, totalTokens: 15});
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };

  const registry = new ToolRegistry();
  registry.register({name: 'tool', description: 'desc', inputSchema: {type: 'object'}}, async () => 'result');

  const orchestrator = createChatOrchestrator(provider, promptBuilder, registry, {hooks});
  await orchestrator.processMessage(session());

  expect(reportedUsage).toEqual({
    inputTokens: 10,
    outputTokens: 10,
    totalTokens: 15,
  });
});

